CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TYPE "BookingStatus" AS ENUM ('PENDING', 'CONFIRMED', 'CANCELLED', 'COMPLETED');
CREATE TABLE "User" ("id" TEXT PRIMARY KEY, "email" TEXT NOT NULL UNIQUE, "passwordHash" TEXT NOT NULL, "name" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Service" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "price" INTEGER NOT NULL, "durationMinutes" INTEGER NOT NULL, "active" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Customer" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "phone" TEXT NOT NULL UNIQUE, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Booking" ("id" TEXT PRIMARY KEY, "customerId" TEXT NOT NULL, "serviceId" TEXT NOT NULL, "startsAt" TIMESTAMPTZ NOT NULL, "endsAt" TIMESTAMPTZ NOT NULL, "status" "BookingStatus" NOT NULL DEFAULT 'PENDING', "note" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Booking_customerId_fkey" FOREIGN KEY ("customerId") REFERENCES "Customer"("id"), CONSTRAINT "Booking_serviceId_fkey" FOREIGN KEY ("serviceId") REFERENCES "Service"("id"), CONSTRAINT "Booking_time_order" CHECK ("endsAt" > "startsAt"));
CREATE TABLE "BusinessHour" ("id" TEXT PRIMARY KEY, "weekday" INTEGER NOT NULL UNIQUE, "openMinute" INTEGER NOT NULL, "closeMinute" INTEGER NOT NULL, "active" BOOLEAN NOT NULL DEFAULT true, CONSTRAINT "BusinessHour_range" CHECK ("openMinute" >= 0 AND "closeMinute" <= 1440 AND "closeMinute" > "openMinute"));
CREATE TABLE "ScheduleBlock" ("id" TEXT PRIMARY KEY, "startsAt" TIMESTAMPTZ NOT NULL, "endsAt" TIMESTAMPTZ NOT NULL, "reason" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ScheduleBlock_order" CHECK ("endsAt" > "startsAt"));
CREATE INDEX "Service_active_idx" ON "Service"("active"); CREATE INDEX "Booking_startsAt_idx" ON "Booking"("startsAt"); CREATE INDEX "Booking_status_startsAt_idx" ON "Booking"("status", "startsAt"); CREATE INDEX "ScheduleBlock_startsAt_endsAt_idx" ON "ScheduleBlock"("startsAt", "endsAt");
ALTER TABLE "Booking" ADD CONSTRAINT "Booking_no_active_overlap" EXCLUDE USING gist (tstzrange("startsAt", "endsAt", '[)') WITH &&) WHERE ("status" IN ('PENDING', 'CONFIRMED'));
